CREATE TABLE exchanges (id SMALLSERIAL PRIMARY KEY,code VARCHAR(10) UNIQUE NOT NULL,name VARCHAR(100) NOT NULL,timezone VARCHAR(64) NOT NULL DEFAULT 'Asia/Kolkata');
INSERT INTO exchanges(code,name) VALUES ('NSE','National Stock Exchange of India'),('BSE','BSE Limited');
CREATE TABLE issuers (id BIGSERIAL PRIMARY KEY,isin VARCHAR(12) UNIQUE,legal_name VARCHAR(250) NOT NULL,sector VARCHAR(120),industry VARCHAR(160),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE instruments (id BIGSERIAL PRIMARY KEY,issuer_id BIGINT REFERENCES issuers(id),exchange_id SMALLINT NOT NULL REFERENCES exchanges(id),symbol VARCHAR(50) NOT NULL,exchange_token VARCHAR(80),series VARCHAR(10),instrument_type VARCHAR(20) NOT NULL DEFAULT 'EQUITY',tick_size NUMERIC(12,6),lot_size INTEGER,active BOOLEAN NOT NULL DEFAULT TRUE,source VARCHAR(60) NOT NULL,valid_from TIMESTAMPTZ,valid_to TIMESTAMPTZ,UNIQUE(exchange_id,symbol,series));
CREATE TABLE data_sources (id BIGSERIAL PRIMARY KEY,source_code VARCHAR(60) UNIQUE NOT NULL,display_name VARCHAR(160) NOT NULL,source_class VARCHAR(40) NOT NULL,access_mode VARCHAR(30) NOT NULL,license_reference TEXT,enabled BOOLEAN NOT NULL DEFAULT FALSE,expected_cadence_seconds INTEGER,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE ingestion_runs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),source_id BIGINT REFERENCES data_sources(id),job_name VARCHAR(120) NOT NULL,started_at TIMESTAMPTZ NOT NULL,finished_at TIMESTAMPTZ,status VARCHAR(24) NOT NULL,records_seen BIGINT DEFAULT 0,records_written BIGINT DEFAULT 0,error_message TEXT,cursor_value TEXT);
CREATE TABLE data_quality_events (id BIGSERIAL PRIMARY KEY,source_id BIGINT REFERENCES data_sources(id),instrument_id BIGINT REFERENCES instruments(id),severity VARCHAR(16) NOT NULL,event_type VARCHAR(60) NOT NULL,observed_at TIMESTAMPTZ NOT NULL DEFAULT now(),details JSONB NOT NULL DEFAULT '{}'::jsonb,resolved_at TIMESTAMPTZ);
CREATE TABLE market_candles (instrument_id BIGINT NOT NULL REFERENCES instruments(id),timeframe VARCHAR(8) NOT NULL,candle_time TIMESTAMPTZ NOT NULL,source_id BIGINT REFERENCES data_sources(id),open NUMERIC(18,6) NOT NULL,high NUMERIC(18,6) NOT NULL,low NUMERIC(18,6) NOT NULL,close NUMERIC(18,6) NOT NULL,volume BIGINT NOT NULL,is_complete BOOLEAN NOT NULL DEFAULT FALSE,quality_status VARCHAR(24) NOT NULL DEFAULT 'UNVERIFIED',revision INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(instrument_id,timeframe,candle_time));
CREATE TABLE market_sessions (exchange_id SMALLINT NOT NULL REFERENCES exchanges(id),session_date DATE NOT NULL,session_type VARCHAR(30) NOT NULL,open_time TIMESTAMPTZ,close_time TIMESTAMPTZ,is_trading_day BOOLEAN NOT NULL,source_id BIGINT REFERENCES data_sources(id),PRIMARY KEY(exchange_id,session_date,session_type));
CREATE TABLE corporate_actions (id BIGSERIAL PRIMARY KEY,issuer_id BIGINT REFERENCES issuers(id),instrument_id BIGINT REFERENCES instruments(id),action_type VARCHAR(40) NOT NULL,ex_date DATE,ratio NUMERIC(18,6),cash_amount NUMERIC(18,6),source_id BIGINT REFERENCES data_sources(id),source_revision VARCHAR(80),raw_payload JSONB NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE instrument_features (instrument_id BIGINT NOT NULL REFERENCES instruments(id),feature_time TIMESTAMPTZ NOT NULL,feature_set VARCHAR(80) NOT NULL,values JSONB NOT NULL,version VARCHAR(40) NOT NULL,PRIMARY KEY(instrument_id,feature_time,feature_set,version));
CREATE TABLE personal_holdings (id BIGSERIAL PRIMARY KEY,symbol VARCHAR(50) NOT NULL,asset_type VARCHAR(16) NOT NULL CHECK(asset_type IN ('EQUITY','MUTUAL_FUND')),quantity NUMERIC(20,6) NOT NULL CHECK(quantity>0),average_cost NUMERIC(20,6) NOT NULL CHECK(average_cost>=0),last_price NUMERIC(20,6) CHECK(last_price>=0),price_as_of TIMESTAMPTZ,notes VARCHAR(500),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
